SELECT * FROM (
SELECT "service", count(*) AS value
FROM {{logs}}
WHERE ts >= $start AND ts < $end
GROUP BY "service"
) ORDER BY value DESC LIMIT 10000

SELECT * FROM (
SELECT json_extract_string(CASE WHEN json_valid(labels) THEN labels ELSE NULL END, $jp3) AS "labels[""host,name""]", avg(TRY_CAST("value" AS DOUBLE)) AS value
FROM {{metrics}}
WHERE ts >= $start AND ts < $end AND (((name = $cf0) AND (json_extract_string(CASE WHEN json_valid(labels) THEN labels ELSE NULL END, $jp1) = $p2)))
GROUP BY "labels[""host,name""]"
) ORDER BY value DESC LIMIT 10000

SELECT * FROM (
SELECT "service", quantile_cont((TRY_CAST("duration_us" AS DOUBLE) / NULLIF(CAST($cf0 AS DOUBLE), 0)), $cf1) AS value
FROM {{traces}}
WHERE ts >= $start AND ts < $end
GROUP BY "service"
) ORDER BY value DESC LIMIT 10000
